// 1. Khai báo biến
$primary-color: #6c5ce7;
$text-color: #2d3436;
$border-radius: 8px;
$spacing-md: 16px;

// 2. Sử dụng biến
.hero-card {
  background-color: $primary-color;
  color: white;
  border-radius: $border-radius;
  padding: $spacing-md;
}

.btn-outline {
  color: $primary-color;
  border: 2px solid $primary-color;

  // SASS có sẵn các hàm xử lý màu tuyệt vời!
  &:hover {
    background-color: lighten($primary-color, 30%);
    border-color: darken($primary-color, 10%);
  }
}

.nav-menu {
  background: #333;
  padding: 10px;

  ul {
    list-style: none;
    margin: 0;
  }

  li {
    display: inline-block;
  }

  a {
    color: white;
    text-decoration: none;
    padding: 8px 12px;

    // & đại diện cho '.nav-menu a'
    &:hover {
      background: #e74c8c;
      border-radius: 4px;
    }

    &.active {
      font-weight: bold;
      border-bottom: 2px solid white;
    }
  }
}

// Sử dụng & với BEM (rất phổ biến)
.btn {
  padding: 10px 20px;

  &--primary {
    background: blue;
  }
  &--large {
    font-size: 1.2rem;
  }
}

// File: _variables.scss
$brand: #e74c8c;
$radius: 6px;

// File: _buttons.scss
// Import biến bằng @use, gọi biến qua namespace 'variables'
@use 'variables' as vars;

.btn {
  background: vars.$brand;
  border-radius: vars.$radius;
  color: white;
  padding: 10px 20px;
}

// File: main.scss
// Gom tất cả component lại để build ra 1 file main.css duy nhất
@use 'variables';
@use 'buttons';
@use 'header';
@use 'footer';

// 1. Mixin căn giữa Flexbox
@mixin flex-center($direction: row) {
  display: flex;
  flex-direction: $direction;
  justify-content: center;
  align-items: center;
}

// 2. Mixin tạo Button (có màu mặc định là xanh)
@mixin custom-btn($bg-color: #3498db, $text-color: #fff) {
  background-color: $bg-color;
  color: $text-color;
  padding: 10px 20px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: 0.2s;

  &:hover {
    background-color: darken($bg-color, 15%);
  }
}

// SỬ DỤNG MIXIN:
.hero-container {
  @include flex-center(column); // Truyền tham số column
  height: 300px;
}

.btn-primary {
  @include custom-btn(); // Lấy màu mặc định
}

.btn-danger {
  @include custom-btn(#e74c3c); // Truyền màu đỏ
}

// 1. Định nghĩa Placeholder (bắt đầu bằng %)
%message-box {
  border: 1px solid #ccc;
  padding: 14px;
  border-radius: 8px;
  font-size: 14px;
  margin-bottom: 12px;
}

// 2. Kế thừa thuộc tính
.message-info {
  @extend %message-box;
  background-color: #e3f2fd;
  color: #1976d2;
  border-color: #90caf9;
}

.message-error {
  @extend %message-box;
  background-color: #ffebee;
  color: #c62828;
  border-color: #ef9a9a;
}

/* 
💡 CSS sinh ra sẽ tự nhóm lại gọn gàng:
.message-info, .message-error {
  border: 1px solid #ccc; padding: 14px; ...
}
.message-info { background: ... }
.message-error { background: ... }
*/

// Khai báo biến cơ sở
$base-font-size: 16px;

// Tạo hàm tính toán (hàm phải có @return)
@function px-to-rem($px-value) {
  @return ($px-value / $base-font-size) * 1rem;
}

// Sử dụng hàm
.hero-title {
  font-size: px-to-rem(48px); // Trả về 3rem
  margin-bottom: px-to-rem(24px); // Trả về 1.5rem
}

.card {
  padding: px-to-rem(20px);
  border-radius: px-to-rem(8px);
}

@use 'sass:map';

// Định nghĩa Map cấu hình màu sắc
$theme-colors: (
  'primary': #007bff,
  'secondary': #6c757d,
  'success': #28a745,
  'danger': #dc3545,
  'warning': #ffc107
);

// Định nghĩa Map cấu hình z-index
$z-layers: (
  'base': 1,
  'dropdown': 1000,
  'sticky': 1020,
  'modal': 1050
);

// Sử dụng giá trị từ Map
.btn-primary {
  background-color: map.get($theme-colors, 'primary');
}

.site-header {
  position: sticky;
  top: 0;
  z-index: map.get($z-layers, 'sticky');
}

.modal-backdrop {
  position: fixed;
  z-index: map.get($z-layers, 'modal');
}

$theme-colors: (
  'primary': #6c5ce7,
  'success': #2ecc71,
  'warning': #f1c40f,
  'danger': #e74c3c
);

// Duyệt qua Map màu sắc
@each $name, $color in $theme-colors {
  // #{} là Interpolation (chèn biến vào tên class)
  .text-#{$name} {
    color: $color;
  }

  .bg-#{$name} {
    background-color: $color;
  }
}

/*
CSS Sinh ra tự động:
.text-primary { color: #6c5ce7; }
.bg-primary { background-color: #6c5ce7; }
.text-success { color: #2ecc71; }
... (tạo đủ 8 class)
*/

// Mixin tự động chọn màu chữ trắng/đen tùy vào nền
@mixin text-contrast($bg-color) {
  background-color: $bg-color;

  // Dùng hàm lightness() có sẵn của SASS
  @if lightness($bg-color) > 50% {
    color: #000; // Nền sáng -> Chữ đen
  } @else {
    color: #fff; // Nền tối -> Chữ trắng
  }
}

.card-dark {
  @include text-contrast(#2d3436); // Sinh ra color: #fff
}

.card-light {
  @include text-contrast(#f1f2f6); // Sinh ra color: #000
}

@use 'sass:math';
@use 'sass:color';

$base-color: #3498db;
$container-width: 1200px;

.container {
  // Thay vì 1200px / 2 -> dùng math.div()
  width: math.div($container-width, 2); // 600px
}

.btn-hover {
  // Pha màu base với 20% màu trắng (tạo tint)
  background-color: color.mix(#fff, $base-color, 20%);
}

.btn-active {
  // Tăng/giảm HSL
  background-color: color.adjust($base-color, $lightness: -10%);
}

// 1. Định nghĩa map Breakpoints
$breakpoints: (
  'tablet': 768px,
  'desktop': 1024px,
  'large': 1440px
);

// 2. Định nghĩa Mixin
@mixin respond-to($size) {
  // Lấy giá trị px từ map
  $bp: map-get($breakpoints, $size);

  @media (min-width: $bp) {
    @content; // Nơi chèn khối CSS con
  }
}

// 3. Sử Dụng Cực Kỳ Dễ Đọc
.hero-title {
  font-size: 24px;

  @include respond-to('tablet') {
    font-size: 36px; // Chèn vào khối @content
  }

  @include respond-to('desktop') {
    font-size: 48px;
  }
}
